// SPDX-License-Identifier: Apache-2.0
//
// vk26-alice-4 — the shell: every NIST case of cavp/Hash_DRBG_SHA256.txt,
// generated by proof/Drbg.lean's kernel in User mode under
// tools/hazard3/harness, forever on the chip, once on the RTL.
//
// A case: the 64 KiB region zeroed; kernel.bin's 280 bytes at its start
// (checked against kernel.sha256); then the state where the kernel keeps it
// (the header of proof/Drbg.lean): M blocks, the interval 2, the counter 1,
// the byte 3 before V, V and C as drbg.py instantiates them from NIST's
// entropy, nonce and personalization string, and the number 1. The kernel
// runs three times on the same region, each from where the last left it:
//
//   1, 2   Generate: M blocks of Hashgen to 0x600, V and the counter on
//          (`from_boot`, `generate_twice`); NIST's ReturnedBits are the
//          second's blocks
//   3      the counter, 3, is past the interval: HALT 1, reseed required,
//          nothing written (`reseed_run`)
//
// The kernel's only call is HASHB, ecall with t0 = 2: SHA-256 of a1 bytes at
// a0, written at a2, the arguments held to what the model accepts
// (hashcall.h). The shell answers it on board_hashb and returns.
//
// When each run halts, the checks board.h numbers:
//
//   1 the kernel's bytes were kernel.sha256's
//   2 the Generates halted with 0 and the third with 1, by HALT
//   3 minstret is the RTL's count (gen.py): one number for every Generate,
//     another for the reseed check
//   4 after the second Generate its M blocks are NIST's ReturnedBits, the
//     region's first WINDOW bytes hash to what drbg.py says they hold (V, H,
//     the data, the counter's bytes and word, C, the blocks) and the rest are
//     zero; and after the third, still so
//
// mcycle is read and sent, not checked: HASHB's time is the shell's, and in
// it on the chip.
//
// A step counter is written before each step, for a trap in the shell itself
// to be named.

#include <stdint.h>

#ifndef REGION_SIZE
#define REGION_SIZE 0x10000u
#endif
#include "board.h"
#include "expect.h"
#include "hashcall.h"
#include "sha256.h"

#define csrr(name) ({ uint32_t v; __asm__ volatile ("csrr %0, " #name : "=r"(v)); v; })
#define csrw(name, v) __asm__ volatile ("csrw " #name ", %0" :: "r"(v))
#define PARAMS 0x400u
#define PRE    0x43fu
#define V_AT   0x440u
#define C_AT   0x480u
#define ONE    0x580u
#define OUT    0x600u

extern void enter_payload(void) __attribute__((noreturn));

// hashcall.h's HASH (t0 = 0) is not one of this kernel's calls.
static int (*const unused_hash)(uint32_t, uint32_t, uint32_t) __attribute__((unused)) = hash_args_ok;

static volatile uint32_t step;
static uint32_t round, ci, run, kernel_ok;

static int same(const volatile uint8_t *a, const uint8_t *b, uint32_t n) {
    for (uint32_t i = 0; i < n; i++)
        if (a[i] != b[i]) return 0;
    return 1;
}

static void put_word(volatile uint8_t *r, uint32_t at, uint32_t v) {
    for (uint32_t k = 0; k < 4; k++) r[at + k] = (uint8_t)(v >> (8 * k));
}

static uint32_t get_word(const volatile uint8_t *r, uint32_t at) {
    return r[at] | (uint32_t)r[at + 1] << 8 | (uint32_t)r[at + 2] << 16 | (uint32_t)r[at + 3] << 24;
}

// The region as drbg.py says the second Generate leaves it: the window's hash,
// and zeros past it.
static int region_after(const struct kcase *c) {
    uint8_t d[32];
    if (!board_hash((const uint8_t *)REGION, WINDOW, d) || !same(d, c->after, 32)) return 0;
    volatile uint32_t *w = (volatile uint32_t *)REGION;
    for (uint32_t i = WINDOW / 4; i < REGION_SIZE / 4; i++)
        if (w[i]) return 0;
    return 1;
}

__attribute__((noreturn)) static void next_case(void) {
    step = 2;
    const struct kcase *c = &CASES[ci];
    volatile uint32_t *w = (volatile uint32_t *)REGION;
    for (uint32_t i = 0; i < REGION_SIZE / 4; i++) w[i] = 0;
    volatile uint8_t *r = (volatile uint8_t *)REGION;
    for (uint32_t i = 0; i < KERNEL_LEN; i++) r[i] = KERNEL[i];
    put_word(r, PARAMS, M);
    put_word(r, PARAMS + 4, INTERVAL);
    put_word(r, PARAMS + 8, 1);
    r[PRE] = 3;
    for (uint32_t i = 0; i < 55; i++) {
        r[V_AT + i] = c->v[i];
        r[C_AT + i] = c->c[i];
    }
    r[ONE + 54] = 1;

    step = 3;
    uint8_t d[32];
    sha256((const uint8_t *)REGION, KERNEL_LEN, d);
    kernel_ok = same(d, KERNEL_SHA, 32);
    board_state(round, ci, c->v, c->c);
    run = 1;
    enter_payload();
}

void shell_main(void) {
    step = 1;
    __asm__ volatile ("csrwi mcountinhibit, 4");   // mcycle runs; the harness takes the counters over later
    board_init();
    round = 0;
    ci = 0;
    next_case();
}

// Every trap: the kernel's ecall, a kernel fault, or the shell's own.
void handle(uint32_t *x) {
    uint32_t cause = csrr(mcause), instret = csrr(minstret), cycles = csrr(mcycle);
    if (((csrr(mstatus) >> 11) & 3) == 3) board_fault(step, cause);
    __asm__ volatile ("csrwi mcountinhibit, 4");   // the harness held mcycle too; the LED's wait needs it

    step = 4;
    if (cause == 8 && x[5] == 2) {
        if (!hashb_args_ok(x[10], x[11], x[12]) || !board_hashb((const uint8_t *)x[10], x[11], (uint8_t *)x[12]))
            board_fail(2, cause);
        csrw(mepc, csrr(mepc) + 4);
        return;
    }

    step = 5;
    const struct kcase *c = &CASES[ci];
    volatile uint8_t *r = (volatile uint8_t *)REGION;
    uint32_t gen = run < 3;
    if (cause != 8 || x[5] != 1) board_fail(2, cause);
    if (!kernel_ok) board_fail(1, ci);
    if (x[10] != (gen ? 0u : 1u)) board_fail(2, x[10]);
    if (instret != (gen ? INSTRET_GEN : INSTRET_RESEED)) board_fail(3, instret);
    board_run(round, ci, run, x[10], get_word(r, PARAMS + 8), instret, cycles,
              gen ? (const uint8_t *)(REGION + OUT) : 0, M, gen ? (const uint8_t *)(REGION + V_AT) : 0);

    step = 6;
    if (run >= 2) {
        if (!same(r + OUT, c->want, 32 * M)) board_fail(4, ci);
        if (!region_after(c)) board_fail(4, run);
    }
    if (gen) {
        run++;
        enter_payload();
    }

    step = 7;
    board_case(round, ci, c->name);
    ci++;
    if (ci == NCASES) {
        board_round(round, NCASES);
        round++;
        ci = 0;
    }
    next_case();
}
